text:
{
  "title_novice": "Водоотдача — главный показатель раствора",
  "summary": [
    {"text": "Водоотдача — главный показатель качества глинистого раствора: чем она ниже, тем лучше раствор.", "claims": ["c2"]},
    {"text": "При водоотдаче 4—8 см³/ч электрические методы надёжно определяют параметры неизменённой части коллектора.", "claims": ["c3", "c5"]},
    {"text": "При водоотдаче 20 см³/ч условия изучения коллекторов становятся крайне неблагоприятными.", "claims": ["c7"]}
  ],
  "claims": [
    {"key": "c1", "text": "Параметры глинистого раствора (водоотдача, плотность, минерализация фильтрата) меняют, как проявляются особенности вскрытия пласта.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "Проявление этих особенностей зависит от параметров раствора: водоотдачи, плотности, минерализации фильтрата.", "numbers": [], "question": null},
    {"key": "c2", "text": "Водоотдача — главный показатель качества глинистого раствора. Чем она ниже, тем лучше раствор.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "Водоотдача - основной показатель качества глинистого раствора; чем ниже водоотдача, тем лучше раствор.", "numbers": [], "question": null},
    {"key": "c3", "text": "При оптимальной водоотдаче (4—8 см³/ч) условия изучения разреза геофизическими методами наиболее благоприятны.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "При оптимальной водоотдаче (4—8 см³/ч) условия изучения разреза геофизическими методами наиболее благоприятны", "numbers": ["4—8", "см³/ч"], "question": "q1"},
    {"key": "c4", "text": "При оптимальной водоотдаче глубина проникновения и толщина глинистой корки в коллекторах минимальны.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "поскольку в этом случае глубина проникновения и толщина глинистой корки в коллекторах являются минимальными", "numbers": [], "question": null},
    {"key": "c5", "text": "При оптимальной водоотдаче электрические методы надёжно определяют параметры неизменённой части коллектора.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "Это обеспечивает надежное определение параметров неизмененной части коллектора методами электрометрии", "numbers": [], "question": null},
    {"key": "c6", "text": "При оптимальной водоотдаче малоглубинные методы с высокой вертикальной разрешающей способностью надёжно показывают коллекторские свойства пласта.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "коллекторских свойств пласта методами с высокой вертикальной разрешающей способностью и малой глубинностью (ГГМ, МБК, ЯМР)", "numbers": [], "question": null},
    {"key": "c7", "text": "При высокой водоотдаче (20 см³/ч) условия изучения коллекторов геофизическими методами становятся крайне неблагоприятными.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "При высокой водоотдаче (20 см³/ч) условия изучения разреза и прежде всего коллекторов геофизическими методами становятся крайне неблагоприятными", "numbers": ["20", "см³/ч"], "question": "q1"},
    {"key": "c8", "text": "Глубокое проникновение не позволяет оценить продуктивность коллектора самыми глубинными электрическими методами.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "глубокое проникновение не позволяет оценивать продуктивность коллектора наиболее глубинными методами электрометрии (индукционный зонд, большие потенциал- и градиент-зонды)", "numbers": [], "question": null},
    {"key": "c9", "text": "Толстая глинистая корка делает коллектор недоступным для малоглубинных методов.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "а толстая глинистая корка делает коллектор недоступным для изучения методами с малой глубинностью (ГГМ, МБК, ЯМР)", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Параметры глинистого раствора определяют, какие особенности вскрытия получает пласт вокруг скважины.", "claims": ["c1"], "hypothesis": false},
    {"text": "Напомним: фильтрат — жидкость, уходящая из раствора в пласт. Глинистая корка — слой частиц на стенке скважины.", "claims": [], "hypothesis": false},
    {"text": "Водоотдача — главный показатель качества раствора. Чем она ниже, тем лучше раствор.", "claims": ["c2"], "hypothesis": false},
    {"text": "При оптимальной водоотдаче (4—8 см³/ч) глубина проникновения и толщина корки в коллекторах минимальны.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Поэтому прибор читает в основном неизменённую часть пласта, то есть ту, куда фильтрат не дошёл.", "claims": ["c5"], "hypothesis": false},
    {"text": "Малоглубинные методы — гамма-гамма-метод плотностной (ГГМ), микробоковой каротаж (МБК), ядерно-магнитный метод (ЯМР) — при этом надёжно показывают свойства коллектора.", "claims": ["c6"], "hypothesis": false},
    {"text": "При водоотдаче 20 см³/ч глубокое проникновение закрывает продуктивность коллектора от самых глубоких методов.", "claims": ["c7", "c8"], "hypothesis": false},
    {"text": "Самые глубокие электрические методы здесь — индукционный метод (ИК) и большие потенциал- и градиент-зонды.", "claims": ["c8"], "hypothesis": false},
    {"text": "Толстая глинистая корка делает коллектор недоступным для ГГМ, МБК и ЯМР.", "claims": ["c9"], "hypothesis": false},
    {"text": "Поэтому один и тот же пласт может давать разные ответы при разной водоотдаче раствора.", "claims": ["c7"], "hypothesis": true}
  ],
  "practice": [
    {"text": "Сначала собирает параметры раствора: водоотдачу, плотность и минерализацию фильтрата (количество солей в жидкости).", "claims": ["c1"], "hypothesis": false},
    {"text": "Сравнивает водоотдачу с оптимальным диапазоном 4—8 см³/ч.", "claims": ["c3"], "hypothesis": false},
    {"text": "Если водоотдача около 20 см³/ч, ждёт ограниченных выводов по коллектору от глубоких и малоглубинных методов.", "claims": ["c7", "c8", "c9"], "hypothesis": false},
    {"text": "Решает, на каких методах строить вывод по коллектору, и при плохом растворе ищет другие признаки.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Водоотдача — не единственный параметр. Плотность и минерализация фильтрата тоже меняют проявление особенностей.", "claims": ["c1"], "hypothesis": false},
    {"text": "Выводы о глубине проникновения и корке сказаны именно для коллекторов.", "claims": ["c4"], "hypothesis": false},
    {"text": "Промежуточные значения водоотдачи между 8 и 20 см³/ч в этом фрагменте книги отдельно не разобраны.", "claims": ["c3", "c7"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Почему глубина метода важна", "text": "Каждый метод получает отклик из своей области вокруг скважины. Глубинный метод захватывает дальнюю зону, малоглубинный — ближнюю, где корка и фильтрат.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Оптимальная водоотдача: 4—8 см³/ч.", "claims": ["c3"]},
    {"text": "Высокая водоотдача: 20 см³/ч.", "claims": ["c7"]},
    {"text": "Чем ниже водоотдача, тем лучше раствор.", "claims": ["c2"]},
    {"text": "При оптимальной водоотдаче глубина проникновения и толщина корки в коллекторах минимальны.", "claims": ["c4"]},
    {"text": "Толстая глинистая корка делает коллектор недоступным для ГГМ, МБК и ЯМР.", "claims": ["c9"]}
  ],
  "terms_defined": [
    {"term": "водоотдача", "term_en": "water loss (fluid loss)", "abbr": "", "definition": "Показатель глинистого раствора, от которого зависят глубина проникновения фильтрата и толщина глинистой корки. Чем ниже, тем лучше раствор. В книге записана в см³/ч.", "claims": ["c1", "c2", "c4"]},
    {"term": "глубинность метода", "term_en": "depth of investigation", "abbr": "", "definition": "Насколько далеко от скважины в пласт «видит» метод. Глубинные методы захватывают дальнюю зону, малоглубинные — ближнюю.", "claims": ["c6", "c8", "c9"]},
    {"term": "вертикальная разрешающая способность", "term_en": "vertical resolution", "abbr": "", "definition": "Способность метода различать близкие по глубине скважины слои. Высокая разрешающая способность позволяет точнее определить границы.", "claims": ["c6"]},
    {"term": "неизменённая часть пласта", "term_en": "uninvaded zone", "abbr": "", "definition": "Часть пласта за пределами зоны проникновения, куда фильтрат раствора не дошёл. Электрические методы определяют именно её свойства.", "claims": ["c3", "c5"]}
  ],
